from llm_saea import Plan, benchmark, optimize

PLAN = Plan.from_dict({'surrogate': 'auto', 'operator': 'current_to_best', 'mutation': 0.7, 'crossover': 0.9, 'exploration': 0.45, 'local_fraction': 0.35, 'radius': 0.15, 'population': 36, 'generations': 6, 'reason': 'Stagnation with zero recent improvement signals the reference plan is too exploitative; increase exploration and mutation modestly to escape the flat basin while keeping current_to_best for stable convergence. Auto surrogate lets held-out RMSE pick between RBF and quadratic given the small 24-sample set in 5D. Population trimmed to 36 to preserve expensive budget for more generations, and local_fraction/radius kept moderate for a balanced global-local split.'})

def solve(problem, budget=100, seed=0):
    return optimize(problem, budget=budget, seed=seed, method='saea', plan=PLAN)

if __name__ == '__main__':
    result = solve(benchmark('sphere', 5))
    print({'best_y': result.best_y, 'best_x': result.best_x.tolist()})
